1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"strconv"
9		"strings"
10	
11		"github.com/spf13/cobra"
12	
13		"github.com/entireio/cli/internal/coreapi"
14	)
15	
16	// newRepoCmd is the `entire repo` command group: control-plane
17	// repository lifecycle (create, list within a project, get, delete), the
18	// `mirror` and `visibility` subtrees, plus the `clone` convenience that
19	// resolves a mirror and shells out to `git clone`. Other git content
20	// operations (log, diff, …) remain intentionally out of scope here.
21	func newRepoCmd() *cobra.Command {
22		cmd := &cobra.Command{
23			Use:   "repo",
24			Short: "Manage Entire repositories",
25		}
26		addControlPlaneFlags(cmd)
27		cmd.AddCommand(newRepoCreateCmd())
28		cmd.AddCommand(newRepoListCmd())
29		cmd.AddCommand(newRepoGetCmd())
30		cmd.AddCommand(newRepoDeleteCmd())
31		cmd.AddCommand(newRepoCloneCmd())
32		cmd.AddCommand(newRepoMirrorCmd())
33		cmd.AddCommand(newRepoVisibilityCmd())
34		return cmd
35	}
36	
37	// repoColumns is the human table/field view of a repo, shared by list and
38	// get. CLUSTER/STATE come from optional fields, shown as "-" when unset.
39	var repoColumns = []string{"ID", "NAME", "PROJECT", "CLUSTER", "STATE"}
40	
41	func repoRow(r coreapi.Repo) []string {
42		return []string{r.ID, r.Name, r.OwningProjectId, r.ClusterHost.Or("-"), r.State.Or("-")}
43	}
44	
45	// repoDetailColumns / repoDetailRow extend the shared repo view with the
46	// entire:// clone URL for the single-repo `get` output. The list view stays on
47	// the lean repoColumns — a full clone URL per row would bloat the table — but a
48	// person inspecting one repo wants the URL they can paste into `git clone`
49	// (COR-699). REMOTE is "-" until the repo is provisioned enough to have a
50	// resolvable cluster host + path.
51	var repoDetailColumns = []string{"ID", "NAME", "PROJECT", "CLUSTER", "STATE", "REMOTE"}
52	
53	func repoDetailRow(r coreapi.Repo) []string {
54		remote := repoRemoteURL(r)
55		if remote == "" {
56			remote = "-"
57		}
58		return append(repoRow(r), remote)
59	}
60	
61	// repoRemoteURL synthesizes the entire:// clone/remote URL for a repo from
62	// its resolved cluster host and path — the form `git clone` and
63	// `git remote add` accept, which git-remote-entire reads back as the repo
64	// slug from the URL path. Returns "" when either coordinate is missing (a
65	// still-provisioning repo may not have them yet); a half-formed URL is worse
66	// than none.
67	func repoRemoteURL(r coreapi.Repo) string {
68		host := strings.TrimSpace(r.ClusterHost.Or(""))
69		path := strings.TrimSpace(r.Path.Or(""))
70		if host == "" || path == "" {
71			return ""
72		}
73		return "entire://" + host + "/" + strings.TrimPrefix(path, "/")
74	}
75	
76	// repoCreateOutput renders a created repo as JSON with a synthesized `remote`
77	// field merged in — the entire:// URL callers paste into `git clone` or
78	// `git remote add`. The repo carries a custom marshaler plus arbitrary
79	// additional properties, so it can't simply be embedded in a wrapper struct;
80	// instead it's round-tripped through its own encoder and the remote is merged
81	// into the resulting object. The synthesis only fills a gap: if the wire
82	// object already carries a `remote` (a future first-class field, or one
83	// arriving via additional properties) it's left untouched, so the
84	// server-provided value always wins. The field is omitted when the clone
85	// coordinates aren't resolvable yet rather than emitted half-formed.
86	func repoCreateOutput(r *coreapi.Repo) (any, error) {
87		if r == nil {
88			return nil, errors.New("nil repo")
89		}
90		raw, err := json.Marshal(r)
91		if err != nil {
92			return nil, fmt.Errorf("encode repo: %w", err)
93		}
94		var obj map[string]json.RawMessage
95		if err := json.Unmarshal(raw, &obj); err != nil {
96			return nil, fmt.Errorf("decode repo: %w", err)
97		}
98		if _, ok := obj["remote"]; !ok {
99			if remote := repoRemoteURL(*r); remote != "" {
100				encoded, err := json.Marshal(remote)
101				if err != nil {
102					return nil, fmt.Errorf("encode remote: %w", err)
103				}
104				obj["remote"] = encoded
105			}
106		}
107		return obj, nil
108	}
109	
110	// parseObjectFormat maps the CLI flag value to the wire enum, rejecting
111	// anything other than the two accepted values so a typo fails fast
112	// client-side rather than as an opaque 422 from the server.
113	func parseObjectFormat(s string) (coreapi.CreateRepoInputBodyObjectFormat, error) {
114		switch s {
115		case "sha1":
116			return coreapi.CreateRepoInputBodyObjectFormatSHA1, nil
117		case "sha256":
118			return coreapi.CreateRepoInputBodyObjectFormatSHA256, nil
119		default:
120			return "", fmt.Errorf("invalid object format %q: must be \"sha1\" or \"sha256\"", s)
121		}
122	}
123	
124	func newRepoCreateCmd() *cobra.Command {
125		var (
126			projectID    string
127			clusterHost  string
128			objectFormat string
129		)
130		cmd := &cobra.Command{
131			Use:   "create <name>",
132			Short: "Create a repository in a project",
133			Args:  cobra.ExactArgs(1),
134			RunE: func(cmd *cobra.Command, args []string) error {
135				var format coreapi.CreateRepoInputBodyObjectFormat
136				if objectFormat != "" {
137					parsed, err := parseObjectFormat(objectFormat)
138					if err != nil {
139						cmd.SilenceUsage = true
140						return err
141					}
142					format = parsed
143				}
144				return runCoreMutation(cmd, func(ctx context.Context, c *coreapi.Client) (string, any, error) {
145					projID, err := resolveProjectRef(ctx, c, projectID)
146					if err != nil {
147						return "", nil, err
148					}
149					body := &coreapi.CreateRepoInputBody{
150						Name:      args[0],
151						ProjectId: projID,
152					}
153					if clusterHost != "" {
154						body.ClusterHost = coreapi.NewOptString(clusterHost)
155					}
156					if format != "" {
157						body.ObjectFormat = coreapi.NewOptCreateRepoInputBodyObjectFormat(format)
158					}
159					created, err := c.CreateRepo(ctx, body)
160					if err != nil {
161						return "", nil, err
162					}
163					wire, err := repoCreateOutput(created)
164					if err != nil {
165						return "", nil, err
166					}
167					msg := fmt.Sprintf("✓ Created repository %s (%s)", created.Name, created.ID)
168					if remote := repoRemoteURL(*created); remote != "" {
169						msg += "\n  Remote: " + remote
170					}
171					return msg, wire, nil
172				})
173			},
174		}
175		cmd.Flags().StringVar(&projectID, "project", "", "Owning project (name or ULID) (required)")
176		cmd.Flags().StringVar(&clusterHost, "cluster-host", "", "Public host of the cluster to pin the repo to (defaults to the jurisdiction default)")
177		cmd.Flags().StringVar(&objectFormat, "object-format", "", "Git object format for the repository: sha1 or sha256 (defaults to the server default)")
178		markRequired(cmd, "project")
179		addJSONFlag(cmd)
180		return cmd
181	}
182	
183	func newRepoListCmd() *cobra.Command {
184		var limit, pageSize int
185		var all, noPager bool
186		var pageToken string
187		cmd := &cobra.Command{
188			Use:   "list <project>",
