22	// entireDirCheckExemptions is the full set of commands allowed to run when
23	// `.entire` is not a real directory, and why each one is allowed. Guarded is
24	// the default; a command belongs here only when it neither reads nor writes
25	// anything under `.entire`.
26	//
27	// Keys are command paths as cobra reports them, and the annotation is
28	// inherited, so a group root covers its subcommands. TestEntireDirCheckExemptions
29	// fails on an exemption missing from this map and on an entry that no longer
30	// matches the tree, which is what stops an exemption being added quietly to
31	// make a failing test pass.
32	//
33	// Deliberately absent: `help` and `agent-help`. Someone asking what they can do
34	// in this repo is told the repo is broken rather than handed a working command
35	// list. `entire <command> --help` is unaffected either way — cobra returns
36	// flag.ErrHelp before it runs any PersistentPreRunE.
37	var entireDirCheckExemptions = map[string]string{
38		"entire auth":       "reads ~/.config/entire and the OS keyring, never the repo",
39		"entire login":      "control-plane login; user-level credentials only",
40		"entire logout":     "control-plane logout; user-level credentials only",
41		"entire org":        "control-plane only",
42		"entire project":    "control-plane only",
43		"entire repo":       "control-plane only; git content operations are out of scope",
44		"entire grant":      "control-plane only",
45		"entire api":        "authenticated passthrough; no local state",
46		"entire plugin":     "managed installs live under the per-user dirs",
47		"entire version":    "prints build information; no repo state",
48		"entire labs":       "prints a static list of experimental workflows",
49		"entire completion": "prints a shell script; users eval it from a shell rc, which a broken repo must not break",
50		"entire doctor":     "diagnostic; has to run ON a broken repo in order to report it",
51	}
