53	// collectExemptions walks the tree and returns every command path whose own
54	// annotations carry the exemption. Children are excluded because they inherit.
55	func collectExemptions(root *cobra.Command) []string {
56		var found []string
57		var walk func(*cobra.Command)
58		walk = func(c *cobra.Command) {
59			if c.Annotations[skipEntireDirCheckAnnotation] == skipEntireDirCheckEnabled {
60				found = append(found, c.CommandPath())
61				return
62			}
63			for _, child := range c.Commands() {
64				walk(child)
65			}
66		}
67		walk(root)
68		sort.Strings(found)
69		return found
70	}
